fun BuildTimerText() {
    var buildTimeText by remember { mutableStateOf("Built: calculating...") }

    LaunchedEffect(Unit) {
        while (true) {
            val diffMin = (System.currentTimeMillis() - BuildConfig.BUILD_TIME) / (1000 * 60)
            buildTimeText = if (diffMin < 1) "Built: just now" else "Built: $diffMin min ago"
            delay(60_000)
        }
    }

    Surface(color = Color.Black.copy(alpha = 0.5f), shape = CircleShape) {
        Text(
            text = buildTimeText,
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
            color = Color.White,
            style = MaterialTheme.typography.labelMedium
        )
    }
}

fun Context.findActivity(): ComponentActivity? = when (this) {
    is ComponentActivity -> this
    is ContextWrapper -> baseContext.findActivity()
    else -> null
}

fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "N/A"
    val seconds = exposureTimeNs / 1_000_000_000.0
    val denom = (1.0 / seconds).roundToInt()
    return if (denom <= 2) {
        "%.1fs".format(seconds)
    } else {
        "1/${denom}s"
    }
}
